package io.github.miklires.mevents.event;import java.util.random.RandomGenerator;public final class RewardSelector{private final RandomGenerator random;public RewardSelector(RandomGenerator random){this.random=random;}public RewardDefinition select(EventDefinition definition){double total=definition.rewards().stream().mapToDouble(RewardDefinition::weight).sum(),target=random.nextDouble(total),cursor=0;for(RewardDefinition reward:definition.rewards()){cursor+=reward.weight();if(target<cursor)return reward;}return definition.rewards().getLast();}}
